# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM İKTİSADINDA SOSYAL YARDIMLAŞMA VE DAYANIŞMA KURUMLARI</text>\n  <rect x="20" y="44" width="152" height="176" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="96" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. ZEKÂT</text>\n  <text x="96" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1d4ed8">(Farz Mali İbadet)</text>\n  <text x="96" y="110" text-anchor="middle" font-size="9" fill="#334155">• Nisap miktarı zenginlik</text>\n  <text x="96" y="126" text-anchor="middle" font-size="9" fill="#334155">ölçüsü ve yılda bir kez.</text>\n  <text x="96" y="144" text-anchor="middle" font-size="9" fill="#334155">• Tevbe 60\'taki 8 sınıfa</text>\n  <text x="96" y="160" text-anchor="middle" font-size="9" fill="#334155">verilen yoksul hakkı.</text>\n  <text x="96" y="182" text-anchor="middle" font-size="9" font-weight="bold" fill="#1e3a8a">• Malı temizler ve arındırır.</text>\n  <rect x="188" y="44" width="152" height="176" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="264" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. SADAKA</text>\n  <text x="264" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">(Geniş Kapsamlı İyilik)</text>\n  <text x="264" y="110" text-anchor="middle" font-size="9" fill="#334155">• Zenginlik ve zaman</text>\n  <text x="264" y="126" text-anchor="middle" font-size="9" fill="#334155">sınırı bulunmaz.</text>\n  <text x="264" y="144" text-anchor="middle" font-size="9" fill="#334155">• Maddi yardımın yanında</text>\n  <text x="264" y="160" text-anchor="middle" font-size="9" fill="#334155">güzel söz ve tebessüm.</text>\n  <text x="264" y="182" text-anchor="middle" font-size="9" font-weight="bold" fill="#14532d">• Fıtır sadakası (Fitre).</text>\n  <rect x="356" y="44" width="152" height="176" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="432" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">3. KARZ-I HASEN</text>\n  <text x="432" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">(Faizsiz Güzel Borç)</text>\n  <text x="432" y="110" text-anchor="middle" font-size="9" fill="#334155">• Darda kalana menfaat</text>\n  <text x="432" y="126" text-anchor="middle" font-size="9" fill="#334155">ve fazlalık beklemeden</text>\n  <text x="432" y="144" text-anchor="middle" font-size="9" fill="#334155">borç para vermek.</text>\n  <text x="432" y="162" text-anchor="middle" font-size="9" fill="#334155">• Faiz (ribâ) sömürüsüne</text>\n  <text x="432" y="182" text-anchor="middle" font-size="9" font-weight="bold" fill="#78350f">karşı ahlaki alternatif.</text>\n  <rect x="524" y="44" width="156" height="176" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="602" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">4. VAKIF &amp; CÂRİYE</text>\n  <text x="602" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#7e22ce">(Kalıcı Kamu Hayrı)</text>\n  <text x="602" y="110" text-anchor="middle" font-size="9" fill="#334155">• Mülkü alım-satımdan</text>\n  <text x="602" y="126" text-anchor="middle" font-size="9" fill="#334155">alıkoyup gelirini kamu</text>\n  <text x="602" y="144" text-anchor="middle" font-size="9" fill="#334155">hizmetine tahsis etmek.</text>\n  <text x="602" y="162" text-anchor="middle" font-size="9" fill="#334155">• Vefattan sonra da</text>\n  <text x="602" y="182" text-anchor="middle" font-size="9" font-weight="bold" fill="#581c87">amel defterini açık tutar.</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SADAKA-İ CÂRİYE (KESİNTİSİZ HAYIR) VE VAKIF MEDENİYETİ</text>\n  <rect x="20" y="46" width="210" height="158" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. SADAKA-İ CÂRİYE ESERLERİ</text>\n  <text x="125" y="92" text-anchor="middle" font-size="9.5" fill="#334155">• Cami, okul, yurt ve kütüphane</text>\n  <text x="125" y="110" text-anchor="middle" font-size="9.5" fill="#334155">• Darüşşifa (hastane) ve aşevi</text>\n  <text x="125" y="128" text-anchor="middle" font-size="9.5" fill="#334155">• Çeşme, köprü, yol ve ağaç dikimi</text>\n  <text x="125" y="148" text-anchor="middle" font-size="9.5" fill="#334155">• İnsanlar ve canlılar yararlandıkça</text>\n  <text x="125" y="166" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1d4ed8">sevabı kesintisiz devam eder.</text>\n  <rect x="245" y="46" width="210" height="158" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">2. FAYDALANILAN İLİM</text>\n  <text x="350" y="92" text-anchor="middle" font-size="9.5" fill="#334155">• İnsanlığa faydalı bilimsel ve</text>\n  <text x="350" y="110" text-anchor="middle" font-size="9.5" fill="#334155">ahlaki eserler kaleme almak.</text>\n  <text x="350" y="128" text-anchor="middle" font-size="9.5" fill="#334155">• Öğrenci yetiştirmek ve ilim</text>\n  <text x="350" y="146" text-anchor="middle" font-size="9.5" fill="#334155">bursları tahsis etmek.</text>\n  <text x="350" y="166" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">• Nesiller boyu süren rehberlik.</text>\n  <rect x="470" y="46" width="210" height="158" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">3. HAYIRLI EVLAT VE VAKIF</text>\n  <text x="575" y="92" text-anchor="middle" font-size="9.5" fill="#334155">• İmanlı, ahlaklı ve topluma</text>\n  <text x="575" y="110" text-anchor="middle" font-size="9.5" fill="#334155">faydalı nesiller yetiştirmek.</text>\n  <text x="575" y="128" text-anchor="middle" font-size="9.5" fill="#334155">• Kamu hizmetlerini devlet bütçesine</text>\n  <text x="575" y="146" text-anchor="middle" font-size="9.5" fill="#334155">yük olmadan gönüllü yürütmek.</text>\n  <text x="575" y="166" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">• Sosyal barış ve merhamet ağı.</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM TÜKETİM AHLAKINDA HARCAMA DENGESİ (İSRÂ 29 &amp; FURKÂN 67)</text>\n  <rect x="20" y="46" width="205" height="158" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="122" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">AŞIRI UÇ: CİMRİLİK (BUHL)</text>\n  <text x="122" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b91c1c">\'Elini boynuna bağlama!\'</text>\n  <text x="122" y="110" text-anchor="middle" font-size="9" fill="#334155">• Malı biriktirip (kenz) piyasadan</text>\n  <text x="122" y="126" text-anchor="middle" font-size="9" fill="#334155">ve ihtiyaç sahibinden esirgemek.</text>\n  <text x="122" y="144" text-anchor="middle" font-size="9" fill="#334155">• Zekât ve infaktan kaçınmak.</text>\n  <text x="122" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#7f1d1d">Sonuç: Toplumsal kin ve bereket kaybı.</text>\n  <rect x="240" y="46" width="220" height="158" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2.2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">ORTA YOL: İTİDAL VE İKTİSAT</text>\n  <text x="350" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">\'İkisi arasında dengeli yol (قَوَامًا)\'</text>\n  <text x="350" y="110" text-anchor="middle" font-size="9" fill="#334155">• İhtiyaca göre ölçülü harcamak.</text>\n  <text x="350" y="126" text-anchor="middle" font-size="9" fill="#334155">• Hem ailesinin rızkını hem de</text>\n  <text x="350" y="142" text-anchor="middle" font-size="9" fill="#334155">yoksulun hakkını (infak) gözetmek.</text>\n  <text x="350" y="164" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#14532d">Sonuç: Huzur, bereket ve sürdürülebilirlik.</text>\n  <rect x="475" y="46" width="205" height="158" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="577" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">AŞIRI UÇ: İSRAF VE TEBZÎR</text>\n  <text x="577" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b91c1c">\'Elini büsbütün açıp saçma!\'</text>\n  <text x="577" y="110" text-anchor="middle" font-size="9" fill="#334155">• Gıda, su, enerji ve zamanı</text>\n  <text x="577" y="126" text-anchor="middle" font-size="9" fill="#334155">gereksiz ve gösteriş için tüketmek.</text>\n  <text x="577" y="144" text-anchor="middle" font-size="9" fill="#334155">• Haram yolda mal saçmak (tebzîr).</text>\n  <text x="577" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#7f1d1d">Sonuç: Yoksulluk ve çevre tahribatı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
